/** The markup for one graphic, or `undefined` for a name nothing paints. */
export function getGraphicThumbnailSvg(name: TacticalGraphicName | string): string | undefined {
    return GRAPHIC_THUMBNAIL_SVGS[name as TacticalGraphicName];
}

const urlCache = new Map<string, string>();

/**
 * The same thumbnail as a `data:` URI, ready for `<img src>`.
 *
 * Percent-encoded rather than base64 — it is a third smaller and stays readable in
 * devtools. Built on first ask and cached, so a picker that renders the same option
 * on every keystroke encodes each one once.
 */
export function getGraphicThumbnailUrl(name: TacticalGraphicName | string): string | undefined {
    const cached = urlCache.get(name as string);
    if (cached) return cached;
    const svg = getGraphicThumbnailSvg(name);
    if (!svg) return undefined;
    const url = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    urlCache.set(name as string, url);
    return url;
}
